using Gtk 4.0;
using Adw 1;

template $SolanumPreferencesWindow : Adw.PreferencesWindow {
  search-enabled: false;

  Adw.PreferencesPage {
    Adw.PreferencesGroup {
      title: _("Session Length");
      description: _("The length of each session type in minutes. Changes apply to the next session of each type.");

      Adw.SpinRow lap_spin {
        title: _("Lap Length");
        numeric: true;
        adjustment: Gtk.Adjustment adjustment {
          lower: 1;
          upper: 99;
          step-increment: 1;
        };
      }

      Adw.SpinRow short_break_spin {
        title: _("Short Break Length");
        numeric: true;
        adjustment: Gtk.Adjustment {
          lower: bind adjustment.lower;
          upper: bind adjustment.upper;
          step-increment: bind adjustment.step-increment;
        };
      }

      Adw.SpinRow long_break_spin {
        title: _("Long Break Length");
        numeric: true;
        adjustment: Gtk.Adjustment {
          lower: bind adjustment.lower;
          upper: bind adjustment.upper;
          step-increment: bind adjustment.step-increment;
        };
      }
    }

    Adw.PreferencesGroup {
      Adw.SpinRow session_count_spin {
        title: _("Sessions Until Long Break");
        numeric: true;
        adjustment: Gtk.Adjustment {
          lower: bind adjustment.lower;
          upper: bind adjustment.upper;
          step-increment: bind adjustment.step-increment;
        };
      }
    }

    Adw.PreferencesGroup {
      Adw.SwitchRow fullscreen_switch {
        title: _("Fullscreen During Breaks");
      }
    }
  }
}

using Gtk 4.0;
using Adw 1;

template $SolanumWindow : Adw.ApplicationWindow {
  default-width: 360;
  default-height: 360;
  height-request: 294;
  default-widget: timer_button;
  content: Adw.ToolbarView {
    [top]
    Adw.HeaderBar {
      show-title: false;
    }

    content: Gtk.Box {
      orientation: vertical;
      valign: center;
      vexpand: true;
      spacing: 6;
      styles ["main-box"]

      Gtk.Label lap_label {
        styles ["heading", "dim-label"]
      }

      Gtk.Label timer_label {
        styles ["timer-label", "accent", "blinking"]
      }

      Gtk.CenterBox {
        margin-bottom: 48;
        halign: center;

        [center]
        Gtk.Box {
          spacing: 12;
          halign: center;

          Gtk.Button timer_button {
            tooltip-text: _("Toggle Timer");
            icon-name: "media-playback-start-symbolic";
            action-name: "win.toggle-timer";
            valign: center;
            styles ["circular", "large", "suggested-action"]
          }

          Gtk.Button skip_button {
            tooltip-text: _("Skip");
            icon-name: "media-seek-forward-symbolic";
            action-name: "win.skip";
            valign: center;
            styles ["circular", "large"]
          }
        }

        [end]
        Gtk.MenuButton menu_button {
          primary: true;
          tooltip-text: _("Main Menu");
          menu-model: app_menu;
          icon-name: "open-menu-symbolic";
          halign: end;
          valign: center;
          margin-start: 12;
          styles ["circular"]
        }
      }
    };
  };

  Adw.Breakpoint large_text_bp {
    condition ("min-width: 800sp and min-height: 800sp")
  }
}

menu app_menu {
  section {
    item (_("Reset Sessions"), "win.reset")
  }

  section {
    item (_("_Preferences"), "app.preferences")
    item (_("_Keyboard Shortcuts"), "win.show-help-overlay")
    item (_("_About Solanum"), "app.about")
  }
}
